@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/source-code-pro";

/* Light (faithful): white page, navy ink, slate secondary text, one indigo for actions. */
:root {
  --background: #ffffff;
  --foreground: #061b31;
  --card: #ffffff;
  --card-foreground: #061b31;
  --popover: #ffffff;
  --popover-foreground: #061b31;
  --primary: #533afd;
  --primary-foreground: #ffffff;
  --secondary: #f6f9fc;
  --secondary-foreground: #061b31;
  --muted: #f8fafd;
  --muted-foreground: #5b6b84;
  --accent: #ecebff;
  --accent-foreground: #533afd;
  --destructive: #df1b41;
  --destructive-foreground: #ffffff;
  --border: #e5edf5;
  --input: #d8e2ee;
  --ring: #533afd;
  --highlight: #ff6118;
  --highlight-foreground: #ffffff;
  --glow: #f363f3;
  --chart-1: #ff7600;
  --chart-2: #fb76fa;
  --chart-3: #7232f1;
  --chart-4: #ffcf5e;
  --chart-5: #a9c8ff;
  --sidebar: #f8fafd;
  --sidebar-foreground: #061b31;
  --sidebar-primary: #533afd;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #ecebff;
  --sidebar-accent-foreground: #533afd;
  --sidebar-border: #e5edf5;
  --sidebar-ring: #533afd;

  --typeface-body: "Hanken Grotesk Variable", "Hanken Grotesk", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", "Hanken Grotesk", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Source Code Pro Variable", "Source Code Pro", ui-monospace, Menlo, Consolas, monospace;
  --radius: 0.375rem;
  --page-width: 79rem;
  --page-gutter: 1rem;
  --section-y: 4rem;
}

/* Dark: the deep-navy developer band, widened into a whole mode. */
.dark {
  --background: #0d1738;
  --foreground: #ffffff;
  --card: #122054;
  --card-foreground: #ffffff;
  --popover: #15245c;
  --popover-foreground: #ffffff;
  --primary: #5b44ff;
  --primary-foreground: #ffffff;
  --secondary: #172a66;
  --secondary-foreground: #ffffff;
  --muted: #101d4a;
  --muted-foreground: #91a8d0;
  --accent: #23337a;
  --accent-foreground: #b9b9f9;
  --destructive: #ff5c7a;
  --destructive-foreground: #0d1738;
  --border: #1f2f66;
  --input: #2b408a;
  --ring: #8f87ff;
  --highlight: #ff8a4c;
  --highlight-foreground: #0d1738;
  --glow: #f363f3;
  --chart-1: #ff8a3d;
  --chart-2: #fb76fa;
  --chart-3: #8b5cff;
  --chart-4: #ffcf5e;
  --chart-5: #7fa8ff;
  --sidebar: #101d4a;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #5b44ff;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #23337a;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #1f2f66;
  --sidebar-ring: #8f87ff;
}
